import java.util.ArrayList;
import java.util.List;

class Node {
    int data;
    Node left, right;

    Node(int item) {
        data = item;
        left = right = null;
    }
}

public class GenerateBinaryTrees {

    public List<Node> generateTrees(int n) {
        if (n == 0) {
            return new ArrayList<>(); // Empty list for n=0
        }
        return generateTrees(1, n);
    }

    private List<Node> generateTrees(int start, int end) {
        List<Node> list = new ArrayList<>();

        if (start > end) {
            list.add(null);  // Important: Add null for empty subtrees
            return list;
        }

        for (int i = start; i <= end; i++) {
            List<Node> leftSubtrees = generateTrees(start, i - 1);
            List<Node> rightSubtrees = generateTrees(i + 1, end);

            for (Node left : leftSubtrees) {
                for (Node right : rightSubtrees) {
                    Node root = new Node(i);
                    root.left = left;
                    root.right = right;
                    list.add(root);
                }
            }
        }
        return list;
    }


    // Helper function to print inorder traversal of a tree (for testing)
    public void inorder(Node root) {
        if (root != null) {
            inorder(root.left);
            System.out.print(root.data + " ");
            inorder(root.right);
        }
    }

    public static void main(String[] args) {
        GenerateBinaryTrees gbt = new GenerateBinaryTrees();
        List<Node> trees = gbt.generateTrees(3);

        System.out.println("Number of unique Binary Trees: " + trees.size()); // Should be 5 for n=3
        System.out.println("Inorder traversals of generated trees:");


        for (Node tree : trees) {
            gbt.inorder(tree);
            System.out.println(); // New line after each tree's traversal
        }


    }
}
